tool_use_result.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,400;0,9..40,500;0,9..40,700;1,9..40,400&display=swap');

:root {
  --primary: #EB0028;
  --text-dark: #121212;
  --text-secondary: #444444;
  --text-muted: #777777;
  --bg-white: #FFFFFF;
  --bg-light: #F7F7F7;
  --border: #E5E5E5;
  --accent-hover: #C7021F;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: 'DM Sans', system-ui, sans-serif;
  background: var(--bg-white);
  color: var(--text-dark);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.container {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 24px;
  max-width: 640px;
  margin: 0 auto;
  width: 100%;
  text-align: center;
}

/* Hero Logo */
.hero-logo {
  margin-bottom: 48px;
}

.logo-link {
  text-decoration: none;
  display: inline-block;
}

.logo-text {
  font-size: 42px;
  font-weight: 700;
  letter-spacing: -1px;
}

.logo-ideaa {
  color: var(--primary);
}

.logo-missing {
  color: var(--primary);
  opacity: 0.4;
  letter-spacing: 8px;
  margin: 0 2px;
}

.logo-forum {
  color: var(--text-dark);
}

/* Error Section */
.error-section {
  margin-bottom: 36px;
}

.error-title {
  font-size: 28px;
  font-weight: 500;
  color: var(--text-dark);
  margin: 0 0 12px;
  letter-spacing: -0.5px;
}

.error-suggestion {
  font-size: 16px;
  color: var(--text-secondary);
  margin: 0;
}

/* Search */
.search-form {
  width: 100%;
  max-width: 420px;
  margin-bottom: 32px;
}

.search-container {
  position: relative;
  display: flex;
  align-items: center;
}

.search-input {
  width: 100%;
  padding: 16px 52px 16px 20px;
  font-size: 16px;
  font-family: inherit;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--bg-white);
  color: var(--text-dark);
  transition: border-color 0.2s, box-shadow 0.2s;
}

.search-input::placeholder {
  color: var(--text-muted);
}

.search-input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(235, 0, 40, 0.1);
}

.search-button {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  transition: background-color 0.2s, color 0.2s;
}

.search-button:hover {
  background: var(--bg-light);
  color: var(--primary);
}

.search-button:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

/* Error Code Bar */
.error-code-bar {
  width: 100%;
  max-width: 420px;
  padding: 14px 20px;
  background: var(--bg-light);
  border-radius: 6px;
  margin-bottom: 48px;
}

.error-code-text {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  letter-spacing: 0.5px;
}

.error-code-bar::after {
  content: '';
  display: block;
  width: 100%;
  height: 1px;
  background: var(--border);
  margin-top: 32px;
}

/* Next Steps */
.next-steps {
  width: 100%;
  max-width: 420px;
}

.next-steps-title {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin: 0 0 20px;
}

.next-steps-links {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
}

.nav-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 16px;
  color: var(--text-muted);
  text-decoration: none;
  transition: color 0.2s;
  padding: 8px 16px;
}

.nav-link:hover {
  color: var(--primary);
}

.nav-link svg {
  opacity: 0.7;
  transition: opacity 0.2s;
}

.nav-link:hover svg {
  opacity: 1;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--bg-white);
  border-top: 1px solid var(--border);
  padding: 20px 24px;
  box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.08);
  z-index: 100;
}

.cookie-content {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.cookie-message {
  font-size: 14px;
  color: var(--text-secondary);
  margin: 0;
  flex: 1;
  min-width: 300px;
}

.cookie-privacy-link {
  color: var(--primary);
  text-decoration: underline;
  margin-left: 4px;
}

.cookie-actions {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
}

.cookie-preferences-btn {
  padding: 10px 20px;
  font-size: 14px;
  font-family: inherit;
  font-weight: 500;
  border: 2px solid var(--border);
  border-radius: 6px;
  background: var(--bg-white);
  color: var(--text-dark);
  cursor: pointer;
  transition: border-color 0.2s, background-color 0.2s;
}

.cookie-preferences-btn:hover {
  border-color: var(--text-dark);
