  <script>
    // Cookie Consent State
    const COOKIE_CONSENT_KEY = 'ideaforum_cookie_consent';

    function getConsentState() {
      return localStorage.getItem(COOKIE_CONSENT_KEY);
    }

    function setConsentState(state) {
      localStorage.setItem(COOKIE_CONSENT_KEY, state);
    }

    // Show banner if no consent given
    function initCookieBanner() {
      const banner = document.getElementById('cookieBanner');
      if (!getConsentState()) {
        banner.classList.add('visible');
      }
    }

    // Cookie Banner Handlers
    document.getElementById('acceptCookies').addEventListener('click', function() {
      setConsentState('accepted');
      document.getElementById('cookieBanner').classList.remove('visible');
    });

    document.getElementById('cookieClose').addEventListener('click', function() {
      document.getElementById('cookieBanner').classList.remove('visible');
    });

    document.getElementById('managePreferences').addEventListener('click', function(e) {
      e.preventDefault();
      document.getElementById('cookieModal').classList.add('visible');
    });

    // Modal Handlers
    document.getElementById('modalClose').addEventListener('click', function() {
      document.getElementById('cookieModal').classList.remove('visible');
    });

    document.getElementById('cancelPreferences').addEventListener('click', function() {
      document.getElementById('cookieModal').classList.remove('visible');
    });

    document.getElementById('savePreferences').addEventListener('click', function() {
      // Save preferences (in real app, would send to server)
      setConsentState('accepted');
      document.getElementById('cookieModal').classList.remove('visible');
      document.getElementById('cookieBanner').classList.remove('visible');
    });

    // Close modal on overlay click
    document.getElementById('cookieModal').addEventListener('click', function(e) {
      if (e.target === this) {
        this.classList.remove('visible');
      }
    });

    // Search Form Handler
    document.getElementById('searchForm').addEventListener('submit', function(e) {
      e.preventDefault();
      const query = document.getElementById('searchInput').value.trim();
      if (query) {
        // In a real app, would navigate to search results
        window.location.href = '/search?q=' + encodeURIComponent(query);
      }
    });

    // Toggle switch labels update
    document.querySelectorAll('.preference-toggle input:not(:disabled)').forEach(function(checkbox) {
      checkbox.addEventListener('change', function() {
        const label = this.nextElementSibling.nextElementSibling;
        label.textContent = this.checked ? 'Enabled' : 'Disabled';
      });
    });

    // Initialize
    initCookieBanner();
  </script>
